def execute_workflow(
    self, workflow_id: str, executor_func: Callable
) -> Dict[str, Any]:
    workflow = self.workflows[workflow_id]
    # Fail closed on unresolvable dependencies before entering the polling loop.
    all_ids = set(workflow.tasks.keys())
    for task in workflow.tasks.values():
        if task.task_id in task.dependencies:
            raise ValueError(f"Task {task.task_id!r} depends on itself")
        if not set(task.dependencies).issubset(all_ids):
            raise ValueError(f"Task {task.task_id!r} has an unknown dependency")
    reachable: set = set()
    changed = True
    while changed:
        changed = False
        for task in workflow.tasks.values():
            if task.task_id not in reachable and set(task.dependencies).issubset(reachable):
                reachable.add(task.task_id)
                changed = True
    if reachable != all_ids:
